reference_solution:
def is_happy(n):
    def step(value):
        total = 0
        while value:
            value, digit = divmod(value, 10)
            total += digit * digit
        return total
    slow, fast = step(n), step(step(n))
    while fast != 1 and slow != fast:
        slow = step(slow)
        fast = step(step(fast))
    return fast == 1

